starter.css:
/* ===== 全局 ===== */
h1 {
  text-align: center;
  color: #8B2E2E;
  margin: 0;
  font-size: 32px;
}
.subtitle {
  text-align: center;
  color: #C9A96E;
  font-size: 16px;
  margin: 8px 0 0 0;
}
/* ===== 主区域 ===== */
.hero {
  padding: 48px 20px 32px;
}
.navbar {
  display: flex;
  justify-content: center;
  gap: 0;
  border-top: 1px solid #E8DDCC;
  border-bottom: 1px solid #E8DDCC;
  background: #FFFAF2;
}
.navbar a {
  padding: 12px 24px;
  text-decoration: none;
  color: #6B5A4E;
  font-size: 14px;
  font-weight: 500;
  transition: all 0.2s;
}
.navbar a:hover {
  color: #8B2E2E;
}
.navbar a.active {
  color: #8B2E2E;
  border-bottom: 2px solid #C9A96E;
}
.main-layout {
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 20px;
}
/* ===== 节目单 ===== */
.program h2 {
  color: #8B2E2E;
  font-size: 20px;
  margin-bottom: 16px;
}
.program-grid {
  display: grid;
  grid-template-columns: 80px 1fr;
  gap: 10px 16px;
  align-items: baseline;
}
.program-grid .time {
  color: #C9A96E;
  font-weight: 600;
  font-size: 14px;
  font-family: 'Fira Code', monospace;
}
.program-grid .piece {
  color: #3D2B1F;
  font-size: 15px;
}
/* ===== 演奏者卡片 ===== */
.performers {
  margin-top: 40px;
}
.performers h2 {
  color: #8B2E2E;
  font-size: 20px;
  margin-bottom: 16px;
}
.performer-cards {
  display: flex;
  gap: 16px;
  flex-wrap: wrap;
}
.performer {
  flex: 1;
  min-width: 180px;
  background: #FFFAF2;
  border: 1px solid #D4C5A9;
  border-radius: 10px;
  padding: 24px;
  text-align: center;
  transition: all 0.3s ease;
}
.performer:hover {
  border-color: #C9A96E;
  transform: translateY(-3px);
  box-shadow: 0 6px 16px rgba(61, 43, 31, 0.1);
}
.performer h3 {
  color: #8B2E2E;
  margin: 0 0 4px 0;
  font-size: 18px;
}
.performer p {
  color: #C9A96E;
  margin: 0;
  font-size: 13px;
  font-weight: 600;
}
/* ===== 固定购票按钮 ===== */
.buy-btn {
  position: fixed;
  bottom: 24px;
  right: 24px;
  padding: 14px 28px;
  background: #8B2E2E;
  color: #fff;
  font-size: 16px;
  font-weight: 600;
  border: none;
  border-radius: 50px;
  cursor: pointer;
  box-shadow: 0 4px 16px rgba(139, 46, 46, 0.35);
  transition: all 0.3s ease;
  z-index: 100;
}
.buy-btn:hover {
  background: #C94545;
  transform: translateY(-2px);
  box-shadow: 0 6px 24px rgba(139, 46, 46, 0.45);
}
/* ===== 响应式 ===== */
@media (max-width: 640px) {
  .hero {
    padding: 32px 16px 24px;
  }
  h1 {
    font-size: 24px;
  }
  .navbar {
    flex-direction: column;
  }
  .navbar a {
    text-align: center;
    border-bottom: 1px solid #EDE5D5;
  }
  .navbar a.active {
    border-bottom: 1px solid #C9A96E;
  }
  .program-grid {
    grid-template-columns: 1fr;
    gap: 4px;
  }
  .program-grid .time {
    margin-top: 10px;
  }
  .performer-cards {
    flex-direction: column;
  }
  .performer {
    min-width: auto;
  }
  .buy-btn {
    bottom: 16px;
    right: 16px;
    padding: 12px 24px;
    font-size: 14px;
  }
}
